package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.widget.TextView;import com.alsafa.native4.core.*;import java.text.SimpleDateFormat;import java.util.*;
public final class SimpleHomeActivity extends Activity{private CoreDb db;private Native4Services services;@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_simple_home);db=new CoreDb(this);services=new Native4Services(db,"native4-android-alpha");findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.openFull).setOnClickListener(v->startActivity(new Intent(this,AdvancedHomeActivity.class)));findViewById(R.id.openSale).setOnClickListener(v->startActivity(new Intent(this,SaleActivity.class)));findViewById(R.id.openRepair).setOnClickListener(v->startActivity(new Intent(this,DirectPartSaleActivity.class)));findViewById(R.id.openShift).setOnClickListener(v->startActivity(new Intent(this,ClosingActivity.class)));findViewById(R.id.openHandover).setOnClickListener(v->startActivity(new Intent(this,HandoverActivity.class)));refresh();}
@Override protected void onResume(){super.onResume();if(services!=null)refresh();}
private void refresh(){try{DeveloperTodaySummaryStore.Summary s=services.developerToday.read(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));((TextView)findViewById(R.id.simpleMoney)).setText("المدوّر من الإقفال السابق\n"+money(s.carry)+"\n\nمبيعات اليوم\n"+money(s.sales)+"\n\nصيانة اليوم\n"+money(s.repairs));}catch(Exception e){((TextView)findViewById(R.id.simpleMoney)).setText("تعذر قراءة ملخص اليوم: "+msg(e));}}
private static String money(DeveloperTodaySummaryStore.Money m){return String.format(Locale.US,"USD %.2f   |   TRY %.2f   |   SYP %.2f",m.usd,m.tryAmount,m.syp);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}}
